package alphametics

import (
	"errors"
	"sort"
	"strings"
	"unicode"
)

var errNoSolution = errors.New("no solution")

type solver struct {
	names       []string
	addends     [][]int
	result      []int
	coeffs      [][]int
	nonzero     []bool
	values      []int
	used        uint16
	maxCols     int
}

// Solve returns one digit assignment that makes puzzle a valid alphametic sum.
func Solve(puzzle string) (map[string]int, error) {
	s, err := parsePuzzle(puzzle)
	if err != nil {
		return nil, err
	}
	answer, ok := s.search(0, 0)
	if !ok {
		return nil, errNoSolution
	}
	return answer, nil
}

func parsePuzzle(puzzle string) (*solver, error) {
	parts := strings.Split(puzzle, "==")
	if len(parts) != 2 {
		return nil, errors.New("puzzle must contain exactly one == operator")
	}

	leftParts := strings.Split(parts[0], "+")
	right := strings.TrimSpace(parts[1])
	if right == "" {
		return nil, errors.New("empty result")
	}

	names := make([]string, 0, 10)
	index := make(map[rune]int, 10)
	nonzero := make([]bool, 0, 10)

	letter := func(r rune) int {
		if i, ok := index[r]; ok {
			return i
		}
		i := len(names)
		index[r] = i
		names = append(names, string(r))
		nonzero = append(nonzero, false)
		return i
	}

	word := func(text string) ([]int, error) {
		runes := []rune(text)
		if len(runes) == 0 {
			return nil, errors.New("empty word")
		}
		for _, r := range runes {
			if !unicode.IsLetter(r) {
				return nil, errors.New("words must contain only letters")
			}
		}
		letters := make([]int, len(runes))
		for i, r := range runes {
			letters[i] = letter(r)
		}
		if len(runes) > 1 {
			nonzero[letters[len(letters)-1]] = true
		}
		return letters, nil
	}

	addends := make([][]int, 0, len(leftParts))
	maxAddLen := 0
	for _, part := range leftParts {
		w, err := word(strings.TrimSpace(part))
		if err != nil {
			return nil, err
		}
		addends = append(addends, w)
		if len(w) > maxAddLen {
			maxAddLen = len(w)
		}
	}

	resultLetters, err := word(right)
	if err != nil {
		return nil, err
	}
	if len(names) > 10 {
		return nil, errors.New("too many distinct letters")
	}

	maxCols := maxAddLen
	if len(resultLetters) > maxCols {
		maxCols = len(resultLetters)
	}
	coeffs := make([][]int, maxCols)
	for pos := 0; pos < maxCols; pos++ {
		c := make([]int, len(names))
		for _, add := range addends {
			if pos < len(add) {
				c[add[pos]]++
			}
		}
		if pos < len(resultLetters) {
			c[resultLetters[pos]]--
		}
		coeffs[pos] = c
	}

	values := make([]int, len(names))
	for i := range values {
		values[i] = -1
	}

	return &solver{
		names:   names,
		addends: addends,
		result:  resultLetters,
		coeffs:  coeffs,
		nonzero: nonzero,
		values:  values,
		maxCols: maxCols,
	}, nil
}

func (s *solver) search(pos, carry int) (map[string]int, bool) {
	if pos == s.maxCols {
		if carry != 0 || !s.assignRemaining() {
			return nil, false
		}
		answer := make(map[string]int, len(s.names))
		for i, name := range s.names {
			answer[name] = s.values[i]
		}
		return answer, true
	}

	coeff := s.coeffs[pos]
	base := carry
	vars := make([]int, 0, len(coeff))
	for letter, c := range coeff {
		if c == 0 {
			continue
		}
		if s.values[letter] >= 0 {
			base += c * s.values[letter]
		} else {
			vars = append(vars, letter)
		}
	}

	sort.Slice(vars, func(i, j int) bool {
		a, b := vars[i], vars[j]
		ca, cb := absInt(coeff[a]), absInt(coeff[b])
		if ca != cb {
			return ca > cb
		}
		if s.nonzero[a] != s.nonzero[b] {
			return s.nonzero[a]
		}
		return a < b
	})

	if s.enumerateColumn(pos, coeff, vars, 0, base) {
		return s.search(pos+1, 0) // placeholder, replaced below
	}
	return nil, false
}

func (s *solver) enumerateColumn(pos int, coeff []int, vars []int, k, partial int) bool {
	if k == len(vars) {
		if partial < 0 || partial%10 != 0 {
			return false
		}
		return s.search(pos+1, partial/10)
	}

	lo, hi := s.remainingRange(vars[k:], coeff)
	lowTotal, highTotal := partial+lo, partial+hi
	if highTotal < 0 {
		return false
	}
	firstMultiple := 0
	if lowTotal > 0 {
		firstMultiple = ((lowTotal + 9) / 10) * 10
	}
	if firstMultiple > highTotal {
		return false
	}

	v := vars[k]
	c := coeff[v]
	for d := 0; d < 10; d++ {
		bit := uint16(1 << d)
		if s.used&bit != 0 {
			continue
		}
		if d == 0 && s.nonzero[v] {
			continue
		}
		s.used |= bit
		s.values[v] = d
		if s.enumerateColumn(pos, coeff, vars, k+1, partial+c*d) {
			return true
		}
		s.values[v] = -1
		s.used &^= bit
	}
	return false
}

func (s *solver) remainingRange(vars []int, coeff []int) (int, int) {
	minDigit, maxDigit := 10, -1
	for d := 0; d < 10; d++ {
		if s.used&(uint16(1)<<uint(d)) == 0 {
			if d < minDigit {
				minDigit = d
			}
			if d > maxDigit {
				maxDigit = d
			}
		}
	}
	if minDigit > maxDigit {
		return 0, 0
	}

	minSum, maxSum := 0, 0
	for _, v := range vars {
		c := coeff[v]
		if c >= 0 {
			minSum += c * minDigit
			maxSum += c * maxDigit
		} else {
			minSum += c * maxDigit
			maxSum += c * minDigit
		}
	}
	return minSum, maxSum
}

func (s *solver) assignRemaining() bool {
	for v := range s.values {
		if s.values[v] >= 0 {
			continue
		}
		found := false
		for d := 0; d < 10; d++ {
			bit := uint16(1 << d)
			if s.used&bit != 0 || (d == 0 && s.nonzero[v]) {
				continue
			}
			s.used |= bit
			s.values[v] = d
			found = true
			break
		}
		if !found {
			return false
		}
	}
	return true
}

func absInt(n int) int {
	if n < 0 {
		return -n
	}
	return n
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}
