// Solve attempts to solve an alphametics puzzle of the form
// "WORD + WORD == RESULT" and returns the digit assigned to every letter.
func Solve(puzzle string) (map[string]int, error) {
	cols, letters, leading, order, err := parsePuzzle(puzzle)
	if err != nil {
		return nil, err
	}

	s := &solver{columns: cols, order: order, leading: leading}
	for i := range s.assign {
		s.assign[i] = -1
	}
	if !s.dfs() {
		return nil, errNoSolution
	}

	result := make(map[string]int, len(letters))
	for _, l := range letters {
		v := s.assign[int(l-'A')]
		if v < 0 {
			return nil, errNoSolution
		}
		result[string(l)] = v
	}
	return result, nil
}

func parsePuzzle(puzzle string) ([]column, []byte, [26]bool, []byte, error) {
	var leading [26]bool

	parts := strings.Split(puzzle, "==")
	if len(parts) != 2 {
		return nil, nil, leading, nil, errors.New("invalid puzzle")
	}

	rawAddends := strings.Split(parts[0], "+")
	addends := make([]string, 0, len(rawAddends))
	for _, raw := range rawAddends {
		w := strings.ToUpper(strings.TrimSpace(raw))
		if !validWord(w) {
			return nil, nil, leading, nil, errors.New("invalid addend")
		}
		addends = append(addends, w)
	}

	resultWord := strings.ToUpper(strings.TrimSpace(parts[1]))
	if !validWord(resultWord) {
		return nil, nil, leading, nil, errors.New("invalid result")
	}

	maxLen := len(resultWord)
	for _, w := range addends {
		if len(w) > maxLen {
			maxLen = len(w)
		}
		if len(w) > 1 {
			leading[int(w[0]-'A')] = true
		}
	}
	if len(resultWord) > 1 {
		leading[int(resultWord[0]-'A')] = true
	}

	present := [26]bool{}
	freq := [26]int{}
	for _, w := range addends {
		for i := 0; i < len(w); i++ {
			present[int(w[i]-'A')] = true
			freq[int(w[i]-'A')]++
		}
	}
	for i := 0; i < len(resultWord); i++ {
		present[int(resultWord[i]-'A')] = true
		freq[int(resultWord[i]-'A')]++
	}

	letters := make([]byte, 0, 10)
	for i, ok := range present {
		if ok {
			letters = append(letters, byte('A'+i))
		}
	}
	if len(letters) > 10 {
		return nil, nil, leading, nil, errors.New("too many distinct letters")
	}

	columns := make([]column, maxLen)
	firstNeed := [26]int{}
	for i := range firstNeed {
		firstNeed[i] = maxLen + 1
	}
	for c := 0; c < maxLen; c++ {
		coeffs := make(map[byte]int)
		for _, w := range addends {
			if c < len(w) {
				l := w[len(w)-1-c]
				coeffs[l]++
				if firstNeed[int(l-'A')] > c {
					firstNeed[int(l-'A')] = c
				}
			}
		}
		hasResult := c < len(resultWord)
		var res byte
		if hasResult {
			res = resultWord[len(resultWord)-1-c]
		}
		columns[c] = column{coeffs: coeffs, result: res, hasResult: hasResult}
	}

	order := append([]byte(nil), letters...)
	sort.Slice(order, func(i, j int) bool {
		a, b := int(order[i]-'A'), int(order[j]-'A')
		if firstNeed[a] != firstNeed[b] {
			return firstNeed[a] < firstNeed[b]
		}
		if freq[a] != freq[b] {
			return freq[a] > freq[b]
		}
		return order[i] < order[j]
	})

	return columns, letters, leading, order, nil
}

func validWord(w string) bool {
	if w == "" {
		return false
	}
	for i := 0; i < len(w); i++ {
		if w[i] < 'A' || w[i] > 'Z' {
			return false
		}
	}
	return true
}

func (s *solver) dfs() bool {
	if ok, _ := s.propagate(); !ok {
		return false
	}

	var chosen byte
	found := false
	for _, l := range s.order {
		if s.assign[int(l-'A')] < 0 {
			chosen = l
			found = true
			break
		}
	}
	if !found {
		return s.nextCol == len(s.columns) && s.carry == 0
	}

	k := int(chosen - 'A')
	savedCarry, savedNext := s.carry, s.nextCol
	for d := 0; d < 10; d++ {
		if s.used[d] || (s.leading[k] && d == 0) {
			continue
		}
		s.assign[k] = d
		s.used[d] = true

		ok, trail := s.propagate()
		if ok && s.dfs() {
			return true
		}

		for i := len(trail) - 1; i >= 0; i-- {
			kk := int(trail[i] - 'A')
			if v := s.assign[kk]; v >= 0 {
				s.used[v] = false
			}
			s.assign[kk] = -1
		}
		s.used[d] = false
		s.assign[k] = -1
		s.carry, s.nextCol = savedCarry, savedNext
	}
	return false
}

func (s *solver) propagate() (bool, []byte) {
	trail := make([]byte, 0, 2)
	for s.nextCol < len(s.columns) {
		col := s.columns[s.nextCol]
		sum := s.carry
		ready := true
		for l, coeff := range col.coeffs {
			v := s.assign[int(l-'A')]
			if v < 0 {
				ready = false
				break
			}
			sum += coeff * v
		}
		if !ready {
			break
		}

		digit := sum % 10
		nextCarry := sum / 10
		if col.hasResult {
			r := col.result
			rv := s.assign[int(r-'A')]
			if rv < 0 {
				if s.used[digit] || (s.leading[int(r-'A')] && digit == 0) {
					return false, trail
				}
				s.assign[int(r-'A')] = digit
				s.used[digit] = true
				trail = append(trail, r)
			} else if rv != digit {
				return false, trail
			}
		} else if digit != 0 {
			return false, trail
		}

		s.carry = nextCarry
		s.nextCol++
	}
	if s.nextCol == len(s.columns) && s.carry != 0 {
		return false, trail
	}
	return true, trail
}
